{
  "name": "range-regex",
  "version": "1.0.0",
  "description": "Convert a numeric range like \"1-100\" into a single regular expression.",
  "type": "module",
  "main": "src/index.js",
  "bin": {
    "range-regex": "bin/cli.js"
  },
  "scripts": {
    "test": "node --test"
  },
  "keywords": [
    "range",
    "regex",
    "regexp",
    "numeric"
  ],
  "license": "MIT",
  "dependencies": {
    "to-regex-range": "^5.0.1"
  }
}

import toRegexRange from 'to-regex-range';

const RANGE_PATTERN = /^\s*(-?\d+)\s*(?:-{1,2}|\.\.)\s*(-?\d+)\s*$/;

export function parseRange(input) {
  if (typeof input !== 'string') {
    throw new TypeError('parseRange expects a string such as "1-100"');
  }

  const match = RANGE_PATTERN.exec(input);
  if (!match) {
    throw new SyntaxError(`Invalid range: "${input}" (expected e.g. "1-100")`);
  }

  return { min: Number(match[1]), max: Number(match[2]) };
}

export function rangeToRegex(input, options) {
  const { min, max } = typeof input === 'string' ? parseRange(input) : input;

  if (typeof min !== 'number' || typeof max !== 'number') {
    throw new TypeError('rangeToRegex expects a range string or { min, max }');
  }

  if (min > max) {
    throw new RangeError(`Invalid range: min (${min}) must be <= max (${max})`);
  }

  return toRegexRange(min, max, options);
}

export function rangeToRegExp(input, options) {
  return new RegExp(`^(?:${rangeToRegex(input, options)})$`);
}

export default rangeToRegex;

#!/usr/bin/env node
import { rangeToRegex } from '../src/index.js';

const USAGE = `Usage: range-regex <range> [--match <value>]

Convert a numeric range into a single regular expression.

Arguments:
  <range>            Inclusive range, e.g. "1-100" or "1..100"

Options:
  -m, --match <n>    Test a value against the generated expression
  -h, --help         Show this help

Examples:
  range-regex 1-100
  range-regex 1-100 --match 42
`;

function main(argv) {
  const args = [...argv];
  let matchValue;

  const matchIndex = args.findIndex((arg) => arg === '-m' || arg === '--match');
  if (matchIndex !== -1) {
    matchValue = args.splice(matchIndex, 2)[1];
    if (matchValue === undefined) {
      throw new Error('Missing value for --match');
    }
  }

  if (args.includes('-h') || args.includes('--help')) {
    process.stdout.write(USAGE);
    return 0;
  }

  const range = args[0];
  if (!range) {
    process.stderr.write(USAGE);
    return 1;
  }

  const source = rangeToRegex(range);
  process.stdout.write(`${source}\n`);

  if (matchValue !== undefined) {
    const re = new RegExp(`^(?:${source})$`);
    process.stdout.write(`${re.test(matchValue) ? 'match' : 'no match'}\n`);
  }

  return 0;
}

try {
  process.exitCode = main(process.argv.slice(2));
} catch (error) {
  process.stderr.write(`range-regex: ${error.message}\n`);
  process.exitCode = 1;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  parseRange,
  rangeToRegex,
  rangeToRegExp,
} from '../src/index.js';

test('parses dash and dot-dot ranges', () => {
  assert.deepEqual(parseRange('1-100'), { min: 1, max: 100 });
  assert.deepEqual(parseRange(' 1 .. 100 '), { min: 1, max: 100 });
  assert.deepEqual(parseRange('-10--1'), { min: -10, max: -1 });
});

test('rejects malformed ranges', () => {
  assert.throws(() => parseRange('1'), SyntaxError);
  assert.throws(() => parseRange('a-b'), SyntaxError);
});

test('generates a single expression for 1-100', () => {
  const source = rangeToRegex('1-100');
  assert.equal(source, '(?:[1-9]|[1-9][0-9]|100)');
});

test('matches every value inside the range', () => {
  const re = rangeToRegExp('1-100');
  for (let n = 1; n <= 100; n += 1) {
    assert.ok(re.test(String(n)), `expected ${n} to match`);
  }
});

test('rejects values outside the range', () => {
  const re = rangeToRegExp('1-100');
  for (const n of ['0', '101', '1000', '007', '-1', 'abc', '']) {
    assert.ok(!re.test(n), `expected ${n} not to match`);
  }
});

test('supports { min, max } input', () => {
  const re = rangeToRegExp({ min: 1, max: 100 });
  assert.ok(re.test('50'));
  assert.ok(!re.test('0'));
});

test('handles negative ranges', () => {
  const re = rangeToRegExp('-10--1');
  assert.ok(re.test('-10'));
  assert.ok(re.test('-1'));
  assert.ok(!re.test('0'));
});

test('throws when min is greater than max', () => {
  assert.throws(() => rangeToRegex('100-1'), RangeError);
});

